// Profiles sit on pitch curves and transmit force. Compatibility follows from
// rules, never from lists of part pairs: surfaces generated by the same basic
// rack are conjugate whatever their pitch curves.
export type Reference={module:number;pressureAngle:number};
export type Profile=
 |{kind:'involute';module:number;pressureAngle:number;backlash:number}
 |{kind:'library';id:string;reference:Reference;tolerance:number;apexOffset?:number}   // tolerance: relative module deviation; apexOffset: extra apex height of crossed pairs
 |{kind:'generated';from:{element:string;surface:string}}
 |{kind:'belt';pitch:number;toothed:boolean}
 |{kind:'helical';lead:number;starts:number}
 |{kind:'friction'};

export function validateProfile(p:Profile){
 switch(p.kind){
  case 'involute':if(!(p.module>0)||!(p.pressureAngle>=5&&p.pressureAngle<=35)||!(p.backlash>=0))throw Error('Evolventenprofil: Modul, Eingriffswinkel 5–35° und Flankenspiel prüfen.');return;
  case 'library':if(!p.id||!(p.reference.module>0)||!(p.tolerance>=0&&p.tolerance<.5))throw Error('Bibliotheksprofil: Bezugsmodul und Toleranz prüfen.');return;
  case 'generated':if(!p.from?.element||!p.from?.surface)throw Error('Erzeugtes Profil braucht seine Quellfläche.');return;
  case 'belt':if(!(p.pitch>0))throw Error('Riementeilung muss positiv sein.');return;
  case 'helical':if(!(p.lead>0)||!Number.isInteger(p.starts)||p.starts<1)throw Error('Schraubprofil: Steigung und Gangzahl prüfen.');return;
  case 'friction':return;
  default:throw Error('Unbekanntes Profil.');
 }
}
/** Basic rack a profile was generated with, if it has one. */
export function reference(p:Profile):Reference|undefined{
 if(p.kind==='involute')return {module:p.module,pressureAngle:p.pressureAngle};
 if(p.kind==='library')return p.reference;
 if(p.kind==='helical')return {module:p.lead/(Math.PI*p.starts),pressureAngle:20};
 return undefined;
}
const tolerance=(p:Profile)=>p.kind==='library'?p.tolerance:0;
export type Compatibility={ok:true}|{ok:false;reason:string};
/** Whether two profiles mesh. `ids` names the surfaces for generated profiles. */
export function compatible(a:Profile,b:Profile,ids?:{a:{element:string;surface:string};b:{element:string;surface:string}}):Compatibility{
 const same=(x:{element:string;surface:string},y:{element:string;surface:string})=>x.element===y.element&&x.surface===y.surface;
 if(a.kind==='generated'||b.kind==='generated'){
  if(!ids)return {ok:false,reason:'Erzeugtes Profil ohne Flächenbezug.'};
  if(a.kind==='generated'&&same(a.from,ids.b)||b.kind==='generated'&&same(b.from,ids.a))return {ok:true};
  return {ok:false,reason:'Erzeugtes Profil passt nur zu seiner Quellfläche.'};
 }
 if(a.kind==='friction'||b.kind==='friction')return a.kind===b.kind?{ok:true}:{ok:false,reason:'Reibung kämmt nur mit Reibung.'};
 if(a.kind==='belt'||b.kind==='belt'){
  if(a.kind!=='belt'||b.kind!=='belt')return {ok:false,reason:'Riemenprofil braucht ein Riemenprofil.'};
  return Math.abs(a.pitch-b.pitch)<1e-9&&a.toothed===b.toothed?{ok:true}:{ok:false,reason:'Riementeilung oder Verzahnung verschieden.'};
 }
 if(a.kind==='helical'&&b.kind==='helical')return {ok:false,reason:'Zwei Schraubprofile kämmen nicht miteinander.'};
 const ra=reference(a)!,rb=reference(b)!,tol=Math.max(tolerance(a),tolerance(b));
 if(Math.abs(ra.module-rb.module)>tol*Math.max(ra.module,rb.module)+1e-9)return {ok:false,reason:`Module ${ra.module} und ${rb.module} stimmen nicht überein.`};
 if(a.kind==='involute'&&b.kind==='involute'&&Math.abs(ra.pressureAngle-rb.pressureAngle)>1e-9)return {ok:false,reason:'Eingriffswinkel verschieden.'};
 return {ok:true};
}
